window.AUTH=window.AUTH||{};window.AUTH["23-411"]={"d":"23-411","id":"2023/23-411","n":"Murthy v. Missouri","briefs":[{"k":"petitioner","label":"Brief of petitioners Vivek H. Murthy, et al.","date":"2023-12-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/293780/20231219192259919_23-411ts%20Murthy.pdf","side":"pet","n":49},{"k":"united-states","label":"Brief amicus curiae of United States Senator Mark Warner","date":"2023-12-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/294259/20231226144150391_2023.12.26%20FOR%20PRINTER%20Senator%20Warner%20Amicus%20Brief%20-%20Murthy%20v%20Missouri.pdf","side":"us","n":2},{"k":"respondent","label":"Brief of respondents Missouri, et al.","date":"2024-02-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/299644/20240202144405984_2024-02-02%20-%20Murthy%20v.%20Missouri%20-%20Brief%20of%20Respondents%20-%20Final%20with%20Tables.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioners Vivek H. Murthy, et al.","date":"2024-03-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/302221/20240304163443397_23-411rb%20Murthy.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r49_n6io.pdf","tr":true,"items":[{"t":"case","label":"Adickes v. S.H. Kress & Co.","cite":"398 U.S. 144","y":1970,"id":"1969/79","sc":1,"sum":"Petitioner is a white school teacher who was refused service in respondent's lunchroom when she was accompanied by six Negro students, and who was arrested for vagrancy by the Hattiesburg, Mississippi, police when she left respondent's premises. She filed a complaint in the Federal District Court to recover damages alleging deprivation of her right under the Equal Protection Clause not to be discriminated against on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","2":"32, 34, 36","3":"14, 15, 21"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"op":5,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"American Manufacturers Mutual Insurance Co. v. Sullivan","cite":"526 U.S. 40","y":1999,"id":"1998/97-2000","sc":1,"sum":"Further, under Pennsylvania law no due process protection attaches to payment of disputed medical expenses before the reasonableness and necessity of those expenses is determined. The Act does not entitle an employee to payment of all medical treatment, but only that treatment which is reasonable and necessary.","sumSrc":"Oyez","by":{"0":"35, 45"}},{"t":"case","label":"Ashcroft v. American Civil Liberties Union","cite":"535 U.S. 564","y":2002,"id":"2001/00-1293","sc":1,"sum":"The Court held that COPA's reliance on community standards to identify what material is harmful to minors does not by itself render the statute substantially overbroad for First Amendment purposes.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Bantam Books, Inc. v. Sullivan","cite":"372 U.S. 58","y":1963,"id":"1962/118","sc":1,"op":6,"ar":18,"sum":"The system of -informal censorship disclosed by this record violates the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27","2":"25, 30, 36, 38, 39, 41","3":"7, 8"}},{"t":"case","label":"Blum v. Yaretsky","cite":"457 U.S. 991","y":1982,"id":"1981/80-1952","sc":1,"op":1,"ar":4,"sum":"As a participating State in the Medicaid program established by the Social Security Act, New York provides Medicaid assistance to eligible persons who receive care in private nursing homes, which are designated as either \"skilled nursing facilities\" (SNF's) or \"health related facilities\" (HRF's), the latter providing less extensive, and generally less expensive, medical care than the former. The nursing homes are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27","2":"32, 36, 50","3":"8, 13, 19"}},{"t":"case","label":"Board of Regents v. Southworth","cite":"529 U.S. 217","y":2000,"id":"1999/98-1189","sc":1,"sum":"The Court held that the \"First Amendment permits a public university to charge its students an activity fee used to fund a program to facilitate extracurricular student speech if the program is viewpoint neutral.\" Justice Kennedy wrote for the Court that, \"[w]hen a university requires its students to pay fees to support the extracurricular speech of other students, all in the interest of open discussion, it may not prefer some viewpoints to others.\" Justice David H. Souter, in an opinion joined by Justices John Paul Stevens and Stephen G. Breyer, concurred in the judgment only.","sumSrc":"Oyez","by":{"0":"23, 38","3":"16"}},{"t":"case","label":"Brentwood Academy v. Tennessee Secondary School Athletic Association","cite":"531 U.S. 288","y":2001,"id":"2000/99-901","sc":1,"sum":"The Court held that the pervasive entwinement of state school officials in the ostensibly private organization, which regulated school sports, and the state education board's acknowledgment of the organization, indicated that the organization is a state actor for civil rights purposes. \"The nominally private character of the Association is overborne by the pervasive entwinement of public institutions and public officials in its composition and workings, and there is no substantial reason to claim unfairness in applying constitutional standards to it,\" wrote Justice Souter for the majority.","sumSrc":"Oyez","by":{"0":"43","2":"43, 44","3":"18, 19"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","2":"51, 52"}},{"t":"case","label":"Carney v. Adams","cite":"141 S. Ct. 493","y":2020,"id":"2020/19-309","sc":1,"op":1,"sum":"Because plaintiff Adams has not shown that he was “able and ready” to apply for a judicial vacancy in the imminent future, Gratz v. Bollinger, 539 U. S. 244, 262, he has failed to demonstrate Article III standing to challenge the Delaware Constitution’s political balance requirement for appointments to the State’s major courts.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"Changizi v. HHS","cite":"82 F.4th 492","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/82/492/","by":{"0":"18","3":"3"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"op":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Clapper v. Amnesty International USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":5,"ar":2,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"20","2":"27"}},{"t":"case","label":"Colorado v. Connelly","cite":"479 U.S. 157","y":1986,"id":"1986/85-660","sc":1,"sum":"The Court held that because the taking of Connelly's statements as evidence did not involve any element of governmental coercion, no violation of the Due Process Clause occurred. The Court argued that suppressing statements in cases where suspects were not coerced would have no deterrent effect on future violations of the Constitution by the police.","sumSrc":"Oyez","by":{"0":"40, 41"}},{"t":"case","label":"Counterman v. Colorado","cite":"600 U.S. 66","y":2023,"id":"2022/22-138","sc":1,"sum":"To establish that a statement is a “true threat” unprotected by the First Amendment, the State must prove that the defendant had some subjective understanding of the statements’ threatening nature, based on a showing no more demanding than recklessness.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38","2":"38, 41"}},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"op":1,"sum":"The judgment is affirmed. Pp. 351-374; 374-375. 509 F. 2d 1133, affirmed. MR. JUSTICE BRENNAN, joined by MR. JUSTICE WHITE and MR. JUSTICE MARSHALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","2":"49"}},{"t":"case","label":"Gill v. Whitford","cite":"138 S. Ct. 1916","y":2018,"id":"2017/16-1161","sc":1,"sum":"A case in which the Court was asked to decide whether partisan gerrymandering claims are justiciable, but the Court held that the plaintiffs lacked judicial standing.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"op":2,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 22","3":"7"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"0":"50","2":"50"}},{"t":"case","label":"INS v. Legalization Assistance Project","cite":"510 U.S. 1301","y":1993,"url":"https://supreme.justia.com/cases/federal/us/510/1301/","sc":1,"by":{"0":"49"}},{"t":"case","label":"Kennedy v. Warren","cite":"66 F.4th 1199","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/66/1199/","by":{"0":"42, 43"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"op":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"21","2":"23, 24, 25"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"19, 47"}},{"t":"case","label":"Lugar v. Edmondson Oil Co.","cite":"457 U.S. 922","y":1982,"id":"1981/80-1730","sc":1,"sum":"Section 1983 offers relief to those who have their rights unlawfully abridged by actions occurring \"under the color of state law.\" The Court decided that a state was liable for damages caused by unconstitutional conduct when two conditions were met.","sumSrc":"Oyez","by":{"0":"25","3":"18"}},{"t":"case","label":"Manhattan Community Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"op":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"0":"2, 3, 14, 16, 22, 25, 26, 28, 36","2":"1","3":"1, 2, 8, 13, 17, 18"}},{"t":"case","label":"McConnell v. FEC","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"op":1,"sum":"The Court found that regulations in the Campaign Finance Reform Act of 2002 did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"sum":"In an 8-to-1 opinion the Court held that, unlike direct sovereign regulation of speech, Congress enjoys wide latitude when setting spending priorities which may indirectly affect certain forms of expression. The funding of one activity believed to be in the public interest, to the exclusion of another, does not constitute viewpoint discrimination.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"National Rifle Association v. Cuomo","cite":"525 F. Supp. 3d 382","y":2021,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/525/382/","sum":"Describing an alleged offer “not to prosecute [certain] violations” in exchange for compliance.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"O’Handley v. Weber","cite":"62 F.4th 1145","y":2023,"court":"filed June 8","url":"https://www.courtlistener.com/c/F.4th/62/1145/","by":{"0":"28, 30, 39, 40, 45"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"op":6,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 21","2":"28","3":"4"}},{"t":"case","label":"Peery v. Chicago Housing Authority","cite":"791 F.3d 788","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/788/","by":{"0":"28","3":"13"}},{"t":"case","label":"Penthouse International, Ltd. v. Meese","cite":"939 F.2d 1011","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/939/1011/","ar":1,"by":{"0":"23, 24, 35","3":"18"}},{"t":"case","label":"Pleasant Grove City v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"op":2,"sum":"The Court held that a city's refusal to place an organization's monument in a public park is not a violation the organization's First Amendment rights.","sumSrc":"Oyez","by":{"0":"2, 23, 45","3":"7, 16"}},{"t":"case","label":"Roman Catholic Diocese of Brooklyn v. Cuomo","cite":"141 S. Ct. 63","y":2020,"id":"2020/20a87","sc":1,"sum":"Respondent is enjoined from enforcing Executive Order 202.68’s 10- and 25-person occupancy limits on Applicant pending disposition of the appeal in the United States Court of Appeals for the Second Circuit and disposition of the petition for a writ of certiorari, if such writ is timely sought.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46"}},{"t":"case","label":"Schmidt v. Lessard","cite":"414 U.S. 473","y":1974,"id":"1973/73-568","sc":1,"op":4,"sum":"The three-judge District Court's order, in a class action challenging the constitutionality of\" the Wisconsin statutory scheme for involuntary commitment of mental patients, that \"judgm~nt be and hereby is entered in accordance with the Opinion heretofore entered,\" which opinion stated that appellees were entitled to injunctive relief against further enforcement of \"the present Wisconsin scheme,\" is sufficient as an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Schneckloth v. Bustamonte","cite":"412 U.S. 218","y":1973,"id":"1972/71-732","sc":1,"sum":"The Supreme Court held that whether consent is voluntary can be determined from the totality of the circumstances. It is unnecessary to prove that the person who gave consent knew that he had the right to refuse. The Fourth Amendment protection against unreasonable searches and seizures does not require a knowing and intelligent waiver of constitutional rights.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Shurtleff v. City of Boston","cite":"596 U.S. 243","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/243/","sc":1,"by":{"0":"23"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"op":2,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 21","3":"6"}},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"op":19,"ar":9,"sum":"Plaintiffs’ allegations that the social-media-company defendants aided and abetted ISIS in its terrorist attack on a nightclub in Istanbul, Turkey fail to state a claim under 18 U. S. C. §2333(d)(2).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3"}},{"t":"case","label":"United States v. American Library Association","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"op":1,"sum":"In a 6-3 judgment delivered by Chief Justice William H. Rehnquist, the Court held that, because public libraries' use of Internet filtering software does not violate their patrons' First Amendment rights, CIPA does not induce libraries to violate the Constitution and is a valid exercise of Congress's spending power. Justices Sandra Day O'Connor, Antonin Scalia, and Clarence Thomas joined the Chief Justice's opinion.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"op":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 17, 46"}},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Virginia State Board of Pharmacy v. Virginia Citizens Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"op":4,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"0":"21","2":"23"}},{"t":"case","label":"Winter v. NRDC, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"op":4,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"0":"45, 46"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"2, 3, 8, 9, 14, 15, 17, 20-23, 25, 29, 30, 34, 36, 45, 46","3":"1, 2, 7, 8, 14, 16, 17, 21"}},{"t":"usc","label":"47 U.S.C. § 230","url":"https://www.law.cornell.edu/uscode/text/47/230","stext":{"head":"§230. Protection for private blocking and screening of offensive material","paras":[[0,"(a) Findings"],[0,"The Congress finds the following:"],[1,"(1) The rapidly developing array of Internet and other interactive computer services available to individual Americans represent an extraordinary advance in the availability of educational and informational resources to our citizens."],[1,"(2) These services offer users a great degree of control over the information that they receive, as well as the potential for even greater control in the future as technology develops."],[1,"(3) The Internet and other interactive computer services offer a forum for a true diversity of political discourse, unique opportunities for cultural development, and myriad avenues for intellectual activity."],[1,"(4) The Internet and other interactive computer services have flourished, to the benefit of all Americans, with a minimum of government regulation."],[1,"(5) Increasingly Americans are relying on interactive media for a variety of political, educational, cultural, and entertainment services."],[0,"(b) Policy"],[0,"It is the policy of the United States—"],[1,"(1) to promote the continued development of the Internet and other interactive computer services and other interactive media;"],[1,"(2) to preserve the vibrant and competitive free market that presently exists for the Internet and other interactive computer services, unfettered by Federal or State regulation;"],[1,"(3) to encourage the development of technologies which maximize user control over what information is received by individuals, families, and schools who use the Internet and other interactive computer services;"],[1,"(4) to remove disincentives for the development and utilization of blocking and filtering technologies that empower parents to restrict their children's access to objectionable or inappropriate online material; and"],[1,"(5) to ensure vigorous enforcement of Federal criminal laws to deter and punish trafficking in obscenity, stalking, and harassment by means of computer."],[0,"(c) Protection for \"Good Samaritan\" blocking and screening of offensive material"],[0,"(1) Treatment of publisher or speaker"],[1,"No provider or user of an interactive computer service shall be treated as the publisher or speaker of any information provided by another information content provider."],[0,"(2) Civil liability"],[1,"No provider or user of an interactive computer service shall be held liable on account of—"],[2,"(A) any action voluntarily taken in good faith to restrict access to or availability of material that the provider or user considers to be obscene, lewd, lascivious, filthy, excessively violent, harassing, or otherwise objectionable, whether or not such material is constitutionally protected; or"],[2,"(B) any action taken to enable or make available to information content providers or others the technical means to restrict access to material described in paragraph (1).1"],[0,"(d) Obligations of interactive computer service"],[0,"A provider of interactive computer service shall, at the time of entering an agreement with a customer for the provision of interactive computer service and in a manner deemed appropriate by the provider, notify such customer that parental control protections (such as computer hardware, software, or filtering services) are commercially available that may assist the customer in limiting access to material that is harmful to minors. Such notice shall identify, or provide the customer with access to information identifying, current providers of such protections."],[0,"(e) Effect on other laws"],[0,"(1) No effect on criminal law"],[1,"Nothing in this section shall be construed to impair the enforcement of section 223 or 231 of this title, chapter 71 (relating to obscenity) or 110 (relating to sexual exploitation of children) of title 18, or any other Federal criminal statute."],[0,"(2) No effect on intellectual property law"],[1,"Nothing in this section shall be construed to limit or expand any law pertaining to intellectual property."],[0,"(3) State law"],[1,"Nothing in this section shall be construed to prevent any State from enforcing any State law that is consistent with this section. No cause of action may be brought and no liability may be imposed under any State or local law that is inconsistent with this section."],[0,"(4) No effect on communications privacy law"],[1,"Nothing in this section shall be construed to limit the application of the Electronic Communications Privacy Act of 1986 or any of the amendments made by such Act, or any similar State law."],[0,"(5) No effect on sex trafficking law"],[1,"Nothing in this section (other than subsection (c)(2)(A)) shall be construed to impair or limit—"],[2,"(A) any claim in a civil action brought under section 1595 of title 18, if the conduct underlying the claim constitutes a violation of section 1591 of that title;"],[2,"(B) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 1591 of title 18; or"],[2,"(C) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 2421A of title 18, and promotion or facilitation of prostitution is illegal in the jurisdiction where the defendant's promotion or facilitation of prostitution was targeted."],[0,"(f) Definitions"],[0,"As used in this section:"],[0,"(1) Internet"],[1,"The term \"Internet\" means the international computer network of both Federal and non-Federal interoperable packet switched data networks."],[0,"(2) Interactive computer service"],[1,"The term \"interactive computer service\" means any information service, system, or access software provider that provides or enables computer access by multiple users to a computer server, including specifically a service or system that provides access to the Internet and such systems operated or services offered by libraries or educational institutions."],[0,"(3) Information content provider"],[1,"The term \"information content provider\" means any person or entity that is responsible, in whole or in part, for the creation or development of information provided through the Internet or any other interactive computer service."],[0,"(4) Access software provider"],[1,"The term \"access software provider\" means a provider of software (including client or server software), or enabling tools that do any one or more of the following:"],[2,"(A) filter, screen, allow, or disallow content;"],[2,"(B) pick, choose, analyze, or digest content; or"],[2,"(C) transmit, receive, display, forward, cache, search, subset, organize, reorganize, or translate content."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/230?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":6,"head":"§230. Protection for private blocking and screening of offensive material","tname":"Telecommunications","by":{"0":"32"}},{"t":"usc","label":"18 U.S.C. § 2702","url":"https://www.law.cornell.edu/uscode/text/18/2702","by":{"0":"48"}},{"t":"reg","label":"3 C.F.R. pt. 129","url":"https://www.ecfr.gov/current/title-3/part-129","by":{"0":"24"}},{"t":"usc","label":"22 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/22/611","by":{"1":"7"}},{"t":"usc","label":"2 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/2/1601","by":{"1":"7"}},{"t":"case","label":"Anderson v. City of Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2"}},{"t":"case","label":"Backpage.com v. Dart","cite":"807 F.3d 229","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/807/229/","ar":1,"by":{"2":"38"}},{"t":"case","label":"Biden v. Knight First Amend. Inst. at Columbia Univ.","cite":"141 S. Ct. 1220","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1220/","sc":1,"op":20,"ar":2,"by":{"2":"38","3":"8, 21"}},{"t":"case","label":"Borough of Duryea, Pa. v. Guarnieri","cite":"564 U.S. 379","y":2011,"id":"2010/09-1476","sc":1,"sum":"The Court held that state and local government employees may not sue their employers for retaliation under the First Amendment's Petition Clause when they petition the government on matters of private concern.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"sum":"The Court held that a Ku Klux Klan's First Amendment rights were violated by an Ohio criminal syndicalism law.","sumSrc":"Oyez","by":{"2":"35","3":"16"}},{"t":"case","label":"Burton v. Wilmington Parking Auth.","cite":"365 U.S. 715","y":1961,"id":"1960/164","sc":1,"sum":"The Court concluded that the restaurant, as a recipient of assistance by the parking authority, benefited from the city's aid and constituted an financially integral and indispensable part of the state.","sumSrc":"Oyez","by":{"2":"31, 45","3":"18"}},{"t":"case","label":"Christian Legal Soc’y v. Walker","cite":"453 F.3d 853","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/853/","by":{"2":"18, 49"}},{"t":"case","label":"Crowe v. Lucas","cite":"595 F.2d 985","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/595/985/","by":{"2":"43"}},{"t":"case","label":"Dennis v. Sparks","cite":"449 U.S. 24","y":1980,"id":"1980/79-1186","sc":1,"sum":"The action against the private parties accused of conspiring with the judge is not subject to dismissal. Private persons, jointly engaged with state officials in a challenged action, are acting \"under color\" of law for purposes of § 1983 actions. And the judge's immunity from damages liability for an official act that was allegedly the product of a corrupt conspiracy involving bribery of the judge does not change …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43","3":"21"}},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21, 22","3":"4"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25, 30"}},{"t":"case","label":"Dossett v. First State Bank","cite":"399 F.3d 940","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/399/940/","by":{"2":"36"}},{"t":"case","label":"Elonis v. United States","cite":"575 U.S. 723","y":2015,"id":"2014/13-983","sc":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Frazier v. Bd. of Trs. of Nw. Miss. Reg’l Med. Ctr.","cite":"765 F.2d 1278","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/765/1278/","by":{"2":"34, 35"}},{"t":"case","label":"George v. Edholm","cite":"752 F.3d 1206","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1206/","op":1,"by":{"2":"47"}},{"t":"case","label":"Harvey v. Plains Twp. Police Dep’t","cite":"421 F.3d 185","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/421/185/","by":{"2":"47"}},{"t":"case","label":"Horvath v. Westport Libr. Ass’n","cite":"362 F.3d 147","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/362/147/","by":{"2":"45"}},{"t":"case","label":"Kach v. Hose","cite":"589 F.3d 626","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/589/626/","sum":"Recognizing “encouragement short of compulsion” as sufficient.","sumSrc":"brief:2","by":{"2":"34"}},{"t":"case","label":"Kowalski v. Tesmer","cite":"543 U.S. 125","y":2004,"id":"2004/03-407","sc":1,"sum":"The Court held that the attorneys lacked third-party standing to sue on behalf of the Michigan indigent defendants. The attorneys did not have close relationships with the indigent defendants, nor was there a hindrance to these defendants' ability to advance their own constitutional rights against the Michigan scheme.","sumSrc":"Oyez","by":{"2":"30, 31","3":"7"}},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"sum":"Respondents' claim that their First Amendment rights are chilled, due to the mere existence of this data-gathering system, does not constitute a justiciable controversy on the basis of the record in this case, disclosing as it does no showing of objective harm or threat of specific future harm. Pp. 3-16. 144 U. S. App. D. C. 72, 444 F. 2d 947, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27","3":"3"}},{"t":"case","label":"Mahanoy Area Sch. Dist. v. B. L.","cite":"141 S. Ct. 2038","y":2021,"id":"2020/20-255","sc":1,"sum":"The school district’s decision to suspend student B. L. from the cheerleading team for posting to social media (outside of school hours and away from the school’s campus) vulgar language and gestures critical of the school violates the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26"}},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"McIntyre v. Ohio Elec. Comm’n","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"sum":"The freedom to publish anonymously is protected by the First Amendment and \"extends beyond the literary realm to the advocacy of political causes.\" When a law burdens such anonymous speech, the Court applies \"exacting scrutiny,\" upholding the restriction only if it is narrowly tailored to serve an overriding state interest.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Neb. Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"op":15,"ar":6,"sum":"The Court agreed with the trial judge that the murder case would generate \"intense and pervasive pretrial publicity.\" However, the unanimous court held that the practical problems associated with implementing a prior restraint on the press in this case would not have served the accused's rights.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Newberry v. United States","cite":"256 U.S. 232","y":1921,"id":"scdb/1920-108","sc":1,"sum":"1. Section*8 of the “Federal Corrupt Practices Act ” (June 25,,1910, c. 392, 36 Stat. 822; amended August 19, 1911, c. 33, 37 Stat. 25), which undertakes to limit the amount of money which any candidate for the office of Representative in Congress or of United States Senator shall give, contribute, expend, use, or promise, or cause to be given, contributed, expended, used, or promised, in procuring his nomination or …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"N.J. Bankers Ass’n v. Att’y Gen.","cite":"49 F.4th 849","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/49/849/","by":{"2":"30"}},{"t":"case","label":"Norwood v. Harrison","cite":"413 U.S. 455","y":1973,"id":"1972/72-77","sc":1,"op":1,"ar":4,"sum":"A three-judge District Court sustained the validity of a Mississippi statutory program, begun in 1940, under which textbooks are purchased by the State and lent to students in both public and private schools, without reference to whether any participating private school has racially discriminatory policies. The number of private secular schools in Mississippi, with a virtually all-white student population, has …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2, 31, 36","3":"15, 17"}},{"t":"case","label":"N.Y. Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"op":1,"ar":4,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Okwedy v. Molinari","cite":"333 F.3d 339","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/333/339/","ar":1,"by":{"2":"38"}},{"t":"case","label":"Opulent Life Church v. City of Holly Springs","cite":"697 F.3d 279","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/279/","by":{"2":"24"}},{"t":"case","label":"Packingham v. North Carolina","cite":"582 U.S. 98","y":2017,"id":"2016/15-1194","sc":1,"sum":"The Court determined that the North Carolina law prohibiting registered sex offenders from accessing various websites, where minors are known to be active and have accounts, regardless of whether or not the sex offender directly interacted with a minor violates the First Amendment.","sumSrc":"Oyez","by":{"2":"1, 17, 22"}},{"t":"case","label":"Proffitt v. Ridgway","cite":"279 F.3d 503","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/279/503/","by":{"2":"43, 44"}},{"t":"case","label":"Quantity of Copies of Books v. Kansas","cite":"378 U.S. 205","y":1964,"id":"1963/449","sc":1,"sum":"The judgment of the State Supreme Court is reversed. Pp. 206-215. 191 Kan. 13, 379 P. 2d 254, reversed. MR. JUSTICE BRENNAN, joined by THE CHIEF JUSTICE, MR. JUSTICE WHITE, and MR. JUSTICE GOLDBERG, without reaching the question whether the novels were obscene, concluded that the procedure followed in issuing and executing the warrant of seizure prior to a hearing on the issue of obscenity was unconstitutional under …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Rattner v. Netburn","cite":"930 F.2d 204","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/930/204/","by":{"2":"38"}},{"t":"case","label":"Rawson v. Recovery Innovations, Inc.","cite":"975 F.3d 742","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/742/","by":{"2":"32"}},{"t":"case","label":"Rayburn ex rel. Rayburn v. Hogue","cite":"241 F.3d 1341","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/241/1341/","by":{"2":"34"}},{"t":"case","label":"Regal Knitwear Co. v. NLRB","cite":"324 U.S. 9","y":1945,"id":"scdb/1944-125","sc":1,"by":{"2":"50"}},{"t":"case","label":"Rivera v. Rhode Island","cite":"402 F.3d 27","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/402/27/","by":{"2":"37"}},{"t":"case","label":"Roberts v. La. Downs, Inc.","cite":"742 F.2d 221","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/742/221/","by":{"2":"44"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Rudd v. City of Norton Shores","cite":"977 F.3d 503","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/503/","by":{"2":"43"}},{"t":"case","label":"Rumsfeld v. F. for Acad. & Institutional Rts.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"op":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Skinner v. Ry. Lab. Execs.’ Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"sum":"The Court held that the government's interest in assuring safety on the nation's railroads constituted a \"special need\" which justified a departure from standard warrant and probable-cause requirements in searches.","sumSrc":"Oyez","by":{"2":"32, 34","3":"13, 14"}},{"t":"case","label":"Smith v. Wade","cite":"461 U.S. 30","y":1983,"id":"1982/81-1196","sc":1,"sum":"Respondent, while an inmate in a Missouri reformatory for youthful first offenders, was harassed, beaten, and sexually assaulted by his cellmates. He brought suit under 42 U. S. C. § 1983 in Federal District Court against petitioner, a guard at the reformatory, and others, alleging that his Eighth Amendment rights had been violated. Because of petitioner's qualified immunity, as a prison guard, from § 1983 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Story v. Jersey City & B.P.P.R. Co.","cite":"16 N.J. Eq. 13","y":1863,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/N.J.%20Eq./16/13/","by":{"2":"27"}},{"t":"case","label":"Students for Fair Admissions, Inc. v. President & Fellows of Harvard Coll.","cite":"600 U.S. 181","y":2023,"id":"2022/20-1199","sc":1,"sum":"The admissions programs at Harvard College and the University of North Carolina violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"47"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Sutton v. Providence St. Joseph Med. Ctr.","cite":"192 F.3d 826","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/192/826/","by":{"2":"47"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"50","3":"22"}},{"t":"case","label":"Terminiello v. Chicago","cite":"337 U.S. 1","y":1949,"id":"1940-1955/337us1","sc":1,"sum":"In a 5-to-4 decision, the Court held that the \"breach of the peace\" ordinance unconstitutionally infringed upon the freedom of speech.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"op":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"2":"51, 52"}},{"t":"case","label":"United States v. Fulmer","cite":"108 F.3d 1486","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/108/1486/","by":{"2":"39"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"op":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"35, 36"}},{"t":"case","label":"United States v. Houston","cite":"792 F.3d 663","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/663/","by":{"2":"39"}},{"t":"case","label":"United States v. Philip Morris USA Inc.","cite":"566 F.3d 1095","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/566/1095/","by":{"2":"51"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"United States v. Stein","cite":"541 F.3d 130","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/541/130/","sum":"Finding significant encouragement where officials “steered [a private employer] toward [the challenged policy] and then supervised its application in individual cases”.","sumSrc":"brief:2","by":{"2":"36, 45"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"United States Telecom Ass’n v. FCC","cite":"855 F.3d 381","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/855/381/","by":{"2":"32, 33"}},{"t":"case","label":"Utah Republican Party v. Cox","cite":"892 F.3d 1066","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1066/","op":1,"by":{"2":"26"}},{"t":"case","label":"W. Va. State Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Watts v. United States","cite":"394 U.S. 705","y":1969,"id":"1968/1107_misc","sc":1,"sum":"The Court concluded, without hearing arguments, that Watts' statement was \"political hyperbole\". The Court noted, \"The language of the political arena… is often vituperative, abusive, and inexact.\" Thus, considering the \"context, and regarding the expressly conditional nature of the statement and the reaction of the listeners,\" the Court ruled that Watts' statement was not a true threat.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"FEC v. Ted Cruz for Senate","cite":"596 U.S. 289","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/289/","sc":1,"by":{"3":"6"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"sum":"The Court found that the proponents of California's same-sex marriage ban (Proposition 8) do not have standing to appeal the decision that made Proposition 8 unconstitutional.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Jackson v. Metropolitan Edison Co.","cite":"419 U.S. 345","y":1974,"id":"1974/73-5845","sc":1,"sum":"The court affirmed the Third Circuit and held that Metropolitan Edison's termination of Jackson's service did not qualify as state action.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Rendell-Baker v. Kohn","cite":"457 U.S. 830","y":1982,"id":"1981/80-2102","sc":1,"sum":"Respondent school did not act under color of state law when it discharged petitioner employees, and hence petitioners have not stated a claim for relief under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"Simon v. Eastern Kentucky Welfare Rights Organization","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"op":3,"sum":"The District Court should have granted petitioners' motion to dismiss because respondents failed to establish their standing to bring this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Southeastern Promotions, Ltd. v. Conrad","cite":"420 U.S. 546","y":1975,"id":"1974/73-1004","sc":1,"sum":"The Court reversed the Sixth Circuit and held that Chattanooga's denial of the Southeastern's request was a \"prior restraint,\" an attempt to censor speech and prevent it from reaching the public.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"3":"14"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"3":"15, 21"}}]};